// --------------------
// Render sidebar from model
// --------------------
function renderNav(sections) {
  const nav = document.querySelector(".sidebar .nav");
  if (!nav) return;
  nav.innerHTML = "";
  (sections || []).forEach(function (section) {
    if (section.title) {
      const heading = document.createElement("div");
      heading.className = "nav-section";
      heading.textContent = section.title;
      nav.appendChild(heading);
    }
    (section.items || []).forEach(function (item) {
      const a = document.createElement("a");
      a.className = "nav-item" + (item.active ? " active" : "");
      a.setAttribute("href", item.page || item.label || "#");
      let inner = item.icon || "";
      inner += "<span>" + (item.label || "") + "</span>";
      if (item.badge) {
        inner += "<span class='badge'>" + item.badge + "</span>";
      }
      a.innerHTML = inner;
      a.addEventListener("click", function (e) {
        e.preventDefault();

        // Update active state visually
        document.querySelectorAll(".sidebar .nav-item").forEach(function (el) {
          el.classList.remove("active");
        });
        a.classList.add("active");

        // Fire single generic event, pass page/item data as payload
        appsmith.updateModel({
          page: item.page
        });
        appsmith.triggerEvent("navigate");
      });
      nav.appendChild(a);
    });
  });
}

// --------------------
// Init
// --------------------
function initApp() {
  const sections = appsmith.model && appsmith.model.navSections || [];
  renderNav(sections);
}

// --------------------
// Appsmith lifecycle
// --------------------
appsmith.onReady(function () {
  initApp();
});

