    return '<div class="field" data-field="logo"><div class="lbl-row"><span class="lbl">Logo</span><span class="opt">Optional</span></div>' + '<div class="dropzone" id="dz"><span id="dz-prev">' + logoHTML(current, name || "?", 56) + '</span><div><p>' + (hint || "PNG, JPG or SVG, up to 1 MB.") + ' Drop a file here or choose one.</p>' + '<div class="links"><button type="button" class="linkish" id="dz-pick">Choose file</button><button type="button" class="linkish red" id="dz-rm"' + (current ? '' : ' hidden') + '>Remove</button></div></div>' + '<input type="file" id="dz-file" accept="image/png,image/jpeg,image/svg+xml,image/webp" hidden></div><div class="err"></div></div>';
  }
  function wireLogo(root, nameSel) {
    var dz = $("#dz", root),
      file = $("#dz-file", root),
      fld = $('[data-field="logo"]', root);
    function paint() {
      $("#dz-prev", root).innerHTML = logoHTML(D_logo, $(nameSel, root).value || "?", 56);
      $("#dz-rm", root).hidden = !D_logo;
    }
    function take(f) {
      if (!f) return;
      if (!/^image\//.test(f.type)) {
        fld.classList.add("invalid");
        $(".err", fld).textContent = "Choose an image file (PNG, JPG or SVG).";
        return;
      }
      if (f.size > 1048576) {
        fld.classList.add("invalid");
        $(".err", fld).textContent = "This file is over 1 MB. Choose a smaller logo.";
        return;
      }
      fld.classList.remove("invalid");
      var r = new FileReader();
      r.onload = function () {
        D_logo = r.result;
        paint();
      };
      r.readAsDataURL(f);
    }
    $("#dz-pick", root).onclick = function () {
      file.click();
    };
    $("#dz-rm", root).onclick = function () {
      D_logo = null;
      file.value = "";
      paint();
    };
    file.onchange = function () {
      take(file.files[0]);
    };
    dz.ondragover = function (e) {
      e.preventDefault();
      dz.classList.add("drag");
    };
    dz.ondragleave = function () {
      dz.classList.remove("drag");
    };
    dz.ondrop = function (e) {
      e.preventDefault();
      dz.classList.remove("drag");
      take(e.dataTransfer.files[0]);
    };
    $(nameSel, root).addEventListener("input", function () {
      if (!D_logo) paint();
    });
  }

  /* ================= Recipient chips ================= */
  function chipHTML(v, removable, kind) {
    var cls = kind === "support" ? " support" : RECIPIENT_ROLES.indexOf(v) > -1 ? " role" : "";
    return '<span class="rchip' + cls + '">' + esc(v) + (removable ? '<button type="button" data-rm="' + esc(v) + '" aria-label="Remove ' + esc(v) + '">' + I.x + '</button>' : '') + '</span>';
  }
  function chipField(key, label, hint) {
    return '<div class="field" data-field="' + key + '"><div class="lbl-row"><label for="ci-' + key + '">' + label + '</label></div><div class="chipin" data-chipin="' + key + '"></div>' + '<div class="suggest" data-suggest="' + key + '"></div>' + (hint ? '<div class="hint">' + hint + '</div>' : '') + '<div class="err"></div></div>';
  }
  function paintChips(root, key) {
    var box = $('[data-chipin="' + key + '"]', root),
      list = D.chips[key],
      kind = key === "support" ? "support" : "";
    box.innerHTML = list.map(function (v) {
      return chipHTML(v, true, kind);
    }).join("") + '<input id="ci-' + key + '" placeholder="' + (list.length ? '' : kind ? 'e.g. pr.support@jewelex.com' : 'Type an email and press Enter') + '">';
    var sg = $('[data-suggest="' + key + '"]', root);
    sg.innerHTML = kind ? '' : RECIPIENT_ROLES.filter(function (r) {
      return list.indexOf(r) < 0;
    }).map(function (r) {
      return '<button type="button" data-add="' + r + '">+ ' + r + '</button>';
    }).join("");
    sg.onclick = function (e) {
      var b = e.target.closest("[data-add]");
      if (b) {
        list.push(b.getAttribute("data-add"));
        paintChips(root, key);
      }
    };
    var inp = $("input", box);
    inp.onkeydown = function (e) {
      if (e.key === "Enter" || e.key === "," || e.key === "Tab" && inp.value.trim()) {
        e.preventDefault();
        addChip(root, key, inp.value);
      } else if (e.key === "Backspace" && !inp.value && list.length) {
        list.pop();
        paintChips(root, key);
        $("#ci-" + key, root).focus();
      }
    };
    inp.onblur = function () {
      if (inp.value.trim()) addChip(root, key, inp.value, true);
    };
    box.onclick = function (e) {
      var rm = e.target.closest("[data-rm]");
      if (rm) {
        list.splice(list.indexOf(rm.getAttribute("data-rm")), 1);
        paintChips(root, key);
        $("#ci-" + key, root).focus();
      } else if (e.target === box) inp.focus();
    };
  }
  function addChip(root, key, raw, silent) {
    var v = raw.replace(/,/g, "").trim().toLowerCase(),
      fld = $('[data-field="' + key + '"]', root);
    if (!v) return;
    if (!emailOk(v)) {
      if (!silent) {
        fld.classList.add("invalid");
        $(".err", fld).textContent = v + " is not a valid email address.";
      }
      return;
    }
    fld.classList.remove("invalid");
    if (D.chips[key].indexOf(v) < 0) D.chips[key].push(v);
    paintChips(root, key);
    if (!silent) $("#ci-" + key, root).focus();
  }

