          active: true
        });
        return true;
      }
    });
  }
  function authForm(a) {
    var sel = a ? a.subs.slice() : [];
    var picker = S.departments.filter(function (d) {
      return d.active || d.subs.some(function (s) {
        return sel.indexOf(s.id) > -1;
