    }).map(function (d) {
      var subs = d.subs.filter(function (s) {
        return s.active || sel.indexOf(s.id) > -1;
      });
      return '<div class="pick-dept"><label class="pick-head"><input type="checkbox" data-tdept="' + d.id + '"><span class="pick-name">' + esc(d.name) + '</span><span class="pick-count" data-count-for="' + d.id + '"></span></label>' + '<div class="pick-subs">' + subs.map(function (s) {
        return '<label class="pick-sub"><input type="checkbox" class="sr" data-tsub="' + s.id + '" data-parent="' + d.id + '"' + (sel.indexOf(s.id) > -1 ? ' checked' : '') + '><span>' + I.tick + esc(s.name) + '</span></label>';
      }).join("") + '</div></div>';
    }).join("");
    var tip = '<span class="tip" tabindex="0" aria-label="How department selection works">' + I.info + '<span class="tip-body" role="tooltip">' + 'A PR is sent to this approver when its sub-department is selected here <b>and</b> its amount is inside the range below.<br><br>' + 'Tick a department name to select all of its sub-departments. Or click single sub-departments to pick only those.</span></span>';
    var legend = '<div class="pick-legend"><span><i class="lg all"></i>All sub-departments</span><span><i class="lg some"></i>Some sub-departments</span><span><i class="lg"></i>Not included</span></div>';
    openDialog({
      title: a ? "Edit approver" : "Add approver",
      sub: a ? a.name : "PRs in the selected sub-departments and amount range will go to this person.",
      saveLabel: a ? "Save changes" : "Add approver",
      done: a ? "Approver updated" : "Approver added",
      body: '<div class="row2">' + field("name", "Full name", textInput("name", a && a.name, "e.g. Anil Mehta")) + field("email", "Email", textInput("email", a && a.email, "name@jewelex.com", "email")) + '</div>' + '<div class="field" data-field="scope"><div class="lbl-row"><span class="lbl">Departments and sub-departments</span>' + tip + '</div>' + legend + '<div class="picker" id="picker">' + picker + '</div><div class="err"></div></div>' + '<div class="row2">' + field("min", "From amount", '<div class="amount"><span>\u20b9</span>' + textInput("min", a ? a.min : "", "0") + '</div>') + field("max", "Up to amount", '<div class="amount"><span>\u20b9</span>' + textInput("max", a && a.max != null ? a.max : "", "50000") + '</div>') + '</div>' + '<label class="inline-check"><input type="checkbox" id="f-nolimit"' + (a && a.max == null ? ' checked' : '') + '>No upper limit</label>' + '<div class="preview" id="preview" aria-live="polite"></div>',
      setup: function (r) {
        function num(v) {
          return v === "" ? NaN : Number(String(v).replace(/[,\s]/g, "").replace(/\u20b9/g, ""));
        }
        function ids() {
          return $$("[data-tsub]:checked", r).map(function (x) {
            return x.getAttribute("data-tsub");
          });
        }
        function syncDepts() {
          $$("[data-tdept]", r).forEach(function (dc) {
            var id = dc.getAttribute("data-tdept"),
              kids = $$('[data-parent="' + id + '"]', r),
              on = kids.filter(function (k) {
                return k.checked;
              }).length;
            dc.checked = kids.length > 0 && on === kids.length;
            dc.indeterminate = on > 0 && on < kids.length;
            var badge = $('[data-count-for="' + id + '"]', r);
            badge.className = "pick-count" + (on && on === kids.length ? " all" : on ? " some" : "");
            badge.textContent = on === kids.length && on ? "All " + on : on ? on + " of " + kids.length : "None";
          });
        }
        function preview() {
          var min = num(val(r, "min")),
            nol = $("#f-nolimit", r).checked,
            max = nol ? null : num(val(r, "max")),
            sel = ids(),
            p = $("#preview", r);
          $('[name="max"]', r).disabled = nol;
          p.className = "preview";
          if (isNaN(min) || !nol && isNaN(max)) {
            p.className = "preview info";
            p.textContent = "Enter an amount range to see which PRs this person will approve.";
            return;
          }
          var txt = "Approves PRs from " + inr(min) + (nol ? " with no upper limit" : " up to " + inr(max));
          txt += sel.length ? " for " + scopeText(sel) + "." : ". Choose departments above.";
          var hi = max == null ? Infinity : max;
          var clash = S.authorities.filter(function (o) {
            if (a && o.id === a.id || !o.active) return false;
            var ohi = o.max == null ? Infinity : o.max;
            return o.min <= hi && min <= ohi && o.subs.some(function (s) {
              return sel.indexOf(s) > -1;
            });
          });
          if (clash.length) {
            p.className = "preview warn";
            txt += " This overlaps with " + clash.map(function (o) {
              return o.name + " (" + rangeText(o) + ")";
            }).join(", ") + ", so both will receive those PRs.";
          }
          p.textContent = txt;
        }
        $("#picker", r).addEventListener("change", function (e) {
          var t = e.target;
          if (t.hasAttribute("data-tdept")) $$('[data-parent="' + t.getAttribute("data-tdept") + '"]', r).forEach(function (k) {
            k.checked = t.checked;
          });
