        syncDepts();
        preview();
        D.num = num;
        D.ids = ids;
      },
      save: function (r) {
        var name = val(r, "name"),
          email = val(r, "email").toLowerCase(),
          sel = D.ids();
        var min = D.num(val(r, "min")),
          nol = $("#f-nolimit", r).checked,
          max = nol ? null : D.num(val(r, "max"));
        if (!name) return invalid("name", "Enter the approver's name.");
        if (!emailOk(email)) return invalid("email", "Enter a valid email address.");
        if (!sel.length) {
          var f = $('[data-field="scope"]', r);
          f.classList.add("invalid");
          $(".err", f).textContent = "Pick at least one sub-department.";
          f.scrollIntoView({
            block: "nearest"
          });
          return false;
        }
        if (isNaN(min) || min < 0) return invalid("min", "Enter a starting amount of 0 or more.");
        if (!nol && (isNaN(max) || max <= min)) return invalid("max", "Must be more than the starting amount, or tick No upper limit.");
        var data = {
          name: name,
          email: email,
          subs: sel,
          min: min,
          max: max
        };
        if (a) Object.assign(a, data);else S.authorities.push(Object.assign({
          id: uid("a"),
          active: true
        }, data));
        return true;
      }
    });
  }
  function stageForm(s) {
    openDialog({
      title: "Edit recipients",
      sub: s.name + ": " + s.when,
      saveLabel: "Save recipients",
      done: "Recipients updated",
      chips: {
        to: s.to.slice(),
        cc: s.cc.slice(),
        support: s.support.slice()
      },
      body: chipField("to", "To", "Roles are filled in for each PR. For example, Approver means whoever is approving that PR.") + chipField("cc", "Cc") + chipField("support", "Support Cc", "Support team members copied on this email. Add as many as you need."),
      setup: function (r) {
        paintChips(r, "to");
        paintChips(r, "cc");
        paintChips(r, "support");
      },
      save: function (r) {
        ["to", "cc", "support"].forEach(function (k) {
          var i = $("#ci-" + k, r);
          if (i.value.trim()) addChip(r, k, i.value, true);
        });
        if (!D.chips.to.length) {
          var f = $('[data-field="to"]', r);
          f.classList.add("invalid");
          $(".err", f).textContent = "Add at least one recipient.";
          return false;
        }
        s.to = D.chips.to;
        s.cc = D.chips.cc;
        s.support = D.chips.support;
        return true;
      }
    });
  }

  /* ================= Events ================= */
  var TABS = $$(".tab");
  TABS.forEach(function (t, i) {
    t.onclick = function () {
      ui.view = t.getAttribute("data-view");
      render();
    };
    t.onkeydown = function (e) {
      var d = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
      if (!d) return;
      var n = TABS[(i + d + TABS.length) % TABS.length];
      n.click();
      n.focus();
    };
  });
  document.addEventListener("click", function (e) {
    var b = e.target.closest("[data-action]");
    if (!b || b.closest("#dialog")) return;
    var act = b.getAttribute("data-action"),
      id = b.getAttribute("data-id"),
      snap;
    var co = byId(S.companies, ui.company);
    function flip(o, k) {
      o[k] = !o[k];
      render();
    }
    switch (act) {
      case "add-company":
        return companyForm();
      case "edit-company":
        return companyForm(byId(S.companies, id));
      case "pick-company":
        ui.company = id;
        ui.q.units = "";
        return render();
      case "del-company":
        var c = byId(S.companies, id);
        return confirmDel("Delete " + c.name + "?", (c.units.length ? "This also deletes its " + plural(c.units.length, "unit") + ". " : "") + "Existing PRs keep their company name.", function () {
          snap = snapshot();
          S.companies.splice(S.companies.indexOf(c), 1);
          ui.company = S.companies[0] && S.companies[0].id;
          render();
          toast(c.name + " deleted", snap);
        });
      case "add-unit":
        return unitForm();
      case "edit-unit":
        return unitForm(byId(co.units, id));
      case "toggle-unit":
        return flip(byId(co.units, id), "active");
      case "del-unit":
        var u = byId(co.units, id);
        snap = snapshot();
        co.units.splice(co.units.indexOf(u), 1);
        render();
        return toast(u.name + " deleted", snap);
      case "add-dept":
        return deptForm();
      case "edit-dept":
        return deptForm(dept(id));
      case "toggle-dept":
        return flip(dept(id), "active");
      case "del-dept":
        var d = dept(id);
