            return s.id;
          });
          S.authorities.forEach(function (a) {
            a.subs = a.subs.filter(function (s) {
              return sids.indexOf(s) < 0;
            });
          });
          S.departments.splice(S.departments.indexOf(d), 1);
          render();
          toast(d.name + " deleted", snap);
        });
      case "toggle-sub":
        return flip(subOwner(id).s, "active");
      case "del-sub":
        var o = subOwner(id);
        snap = snapshot();
        o.d.subs.splice(o.d.subs.indexOf(o.s), 1);
        S.authorities.forEach(function (a) {
          a.subs = a.subs.filter(function (s) {
            return s !== id;
          });
        });
        render();
        return toast(o.s.name + " removed", snap);
      case "add-cat":
        return catForm();
      case "edit-cat":
        return catForm(byId(S.categories, id));
      case "toggle-cat":
        return flip(byId(S.categories, id), "active");
      case "del-cat":
        var k = byId(S.categories, id);
        snap = snapshot();
        S.categories.splice(S.categories.indexOf(k), 1);
        render();
        return toast(k.name + " deleted", snap);
      case "add-auth":
        return authForm();
      case "edit-auth":
        return authForm(byId(S.authorities, id));
      case "toggle-auth":
        return flip(byId(S.authorities, id), "active");
      case "del-auth":
        var a = byId(S.authorities, id);
        snap = snapshot();
        S.authorities.splice(S.authorities.indexOf(a), 1);
        render();
        return toast(a.name + " removed as approver", snap);
      case "edit-stage":
        return stageForm(byId(S.stages, id));
      case "toggle-stage":
        return flip(byId(S.stages, id), "enabled");
    }
  });
  document.addEventListener("input", function (e) {
    var k = e.target.getAttribute && e.target.getAttribute("data-search");
    if (k) {
      ui.q[k] = e.target.value;
