      d = dept(t.getAttribute("data-addsub"));
    if (!name) return;
    if (d.subs.some(function (s) {
      return s.name.toLowerCase() === name.toLowerCase();
    })) {
      toast(name + " already exists in " + d.name);
      return;
    }
    d.subs.push({
      id: uid("s"),
      name: name,
      active: true
    });
    render();
    toast(name + " added to " + d.name);
    var again = $('[data-addsub="' + d.id + '"]');
    if (again) again.focus();
  });
  render();
}
