      var name=val(r,"name");
      if(!name) return invalid("name","Enter the department name.");
      if(S.departments.some(function(x){ return x.name.toLowerCase()===name.toLowerCase()&&(!d||x.id!==d.id); })) return invalid("name","This department already exists.");
      if(d){ d.name=name; }
      else {
        var subs=val(r,"subs").split(/\n+/).map(function(s){ return s.trim(); }).filter(Boolean).filter(function(s,i,a){ return a.indexOf(s)===i; });
        S.departments.push({id:uid("d"),name:name,active:true,subs:subs.map(function(s){ return {id:uid("s"),name:s,active:true}; })});
      }
      return true;
    }});
}
function catForm(c){
  openDialog({title:c?"Edit category":"Add category",sub:c?c.name:"",saveLabel:c?"Save changes":"Add category",done:c?"Category updated":"Category added",
    body:field("name","Category name",textInput("name",c&&c.name,"e.g. Machinery Purchase"))+
      field("desc","Description",'<textarea class="input" id="f-desc" name="desc" placeholder="What kind of purchases belong here">'+esc(c&&c.desc)+'</textarea>',"Shown to requesters as help text on the PR form."),
    save:function(r){
      var name=val(r,"name");
      if(!name) return invalid("name","Enter the category name.");
      if(S.categories.some(function(x){ return x.name.toLowerCase()===name.toLowerCase()&&(!c||x.id!==c.id); })) return invalid("name","This category already exists.");
      if(c){ c.name=name; c.desc=val(r,"desc"); }
      else S.categories.push({id:uid("k"),name:name,desc:val(r,"desc"),active:true});
      return true;
    }});
}
function authForm(a){
  var sel=a?a.subs.slice():[];
  var picker=S.departments.filter(function(d){ return d.active||d.subs.some(function(s){ return sel.indexOf(s.id)>-1; }); }).map(function(d){
    var subs=d.subs.filter(function(s){ return s.active||sel.indexOf(s.id)>-1; });
    return '<div class="pick-dept"><label class="pick-head"><input type="checkbox" data-tdept="'+d.id+'"><span class="pick-name">'+esc(d.name)+'</span><span class="pick-count" data-count-for="'+d.id+'"></span></label>'+
      '<div class="pick-subs">'+subs.map(function(s){
        return '<label class="pick-sub"><input type="checkbox" class="sr" data-tsub="'+s.id+'" data-parent="'+d.id+'"'+(sel.indexOf(s.id)>-1?' checked':'')+'><span>'+I.tick+esc(s.name)+'</span></label>';
      }).join("")+'</div></div>';
  }).join("");
  var tip='<span class="tip" tabindex="0" aria-label="How department selection works">'+I.info+'<span class="tip-body" role="tooltip">'+
    'A PR is sent to this approver when its sub-department is selected here <b>and</b> its amount is inside the range below.<br><br>'+
    'Tick a department name to select all of its sub-departments. Or click single sub-departments to pick only those.</span></span>';
  var legend='<div class="pick-legend"><span><i class="lg all"></i>All sub-departments</span><span><i class="lg some"></i>Some sub-departments</span><span><i class="lg"></i>Not included</span></div>';
  openDialog({title:a?"Edit approver":"Add approver",sub:a?a.name:"PRs in the selected sub-departments and amount range will go to this person.",saveLabel:a?"Save changes":"Add approver",done:a?"Approver updated":"Approver added",
    body:'<div class="row2">'+field("name","Full name",textInput("name",a&&a.name,"e.g. Anil Mehta"))+field("email","Email",textInput("email",a&&a.email,"name@jewelex.com","email"))+'</div>'+
      '<div class="field" data-field="scope"><div class="lbl-row"><span class="lbl">Departments and sub-departments</span>'+tip+'</div>'+legend+'<div class="picker" id="picker">'+picker+'</div><div class="err"></div></div>'+
      '<div class="row2">'+field("min","From amount",'<div class="amount"><span>\u20b9</span>'+textInput("min",a?a.min:"","0")+'</div>')+
        field("max","Up to amount",'<div class="amount"><span>\u20b9</span>'+textInput("max",a&&a.max!=null?a.max:"","50000")+'</div>')+'</div>'+
      '<label class="inline-check"><input type="checkbox" id="f-nolimit"'+(a&&a.max==null?' checked':'')+'>No upper limit</label>'+
      '<div class="preview" id="preview" aria-live="polite"></div>',
    setup:function(r){
      function num(v){ return v===""?NaN:Number(String(v).replace(/[,\s]/g,"").replace(/\u20b9/g,"")); }
      function ids(){ return $$("[data-tsub]:checked",r).map(function(x){ return x.getAttribute("data-tsub"); }); }
      function syncDepts(){
        $$("[data-tdept]",r).forEach(function(dc){
          var id=dc.getAttribute("data-tdept"), kids=$$('[data-parent="'+id+'"]',r), on=kids.filter(function(k){ return k.checked; }).length;
          dc.checked=kids.length>0&&on===kids.length; dc.indeterminate=on>0&&on<kids.length;
          var badge=$('[data-count-for="'+id+'"]',r);
          badge.className="pick-count"+(on&&on===kids.length?" all":on?" some":"");
          badge.textContent=on===kids.length&&on?"All "+on:on?on+" of "+kids.length:"None";
        });
      }
      function preview(){
        var min=num(val(r,"min")), nol=$("#f-nolimit",r).checked, max=nol?null:num(val(r,"max")), sel=ids(), p=$("#preview",r);
        $('[name="max"]',r).disabled=nol;
        p.className="preview";
        if(isNaN(min)||(!nol&&isNaN(max))){ p.className="preview info"; p.textContent="Enter an amount range to see which PRs this person will approve."; return; }
        var txt="Approves PRs from "+inr(min)+(nol?" with no upper limit":" up to "+inr(max));
        txt+=sel.length?" for "+scopeText(sel)+".":". Choose departments above.";
        var hi=max==null?Infinity:max;
        var clash=S.authorities.filter(function(o){
          if((a&&o.id===a.id)||!o.active) return false;
          var ohi=o.max==null?Infinity:o.max;
          return o.min<=hi&&min<=ohi&&o.subs.some(function(s){ return sel.indexOf(s)>-1; });
        });
        if(clash.length){ p.className="preview warn"; txt+=" This overlaps with "+clash.map(function(o){ return o.name+" ("+rangeText(o)+")"; }).join(", ")+", so both will receive those PRs."; }
        p.textContent=txt;
      }
      $("#picker",r).addEventListener("change",function(e){
        var t=e.target;
        if(t.hasAttribute("data-tdept")) $$('[data-parent="'+t.getAttribute("data-tdept")+'"]',r).forEach(function(k){ k.checked=t.checked; });
        syncDepts(); preview();
      });
      ["min","max"].forEach(function(n){ $('[name="'+n+'"]',r).addEventListener("input",preview); });
      $("#f-nolimit",r).onchange=preview;
      syncDepts(); preview();
      D.num=num; D.ids=ids;
    },
    save:function(r){
      var name=val(r,"name"), email=val(r,"email").toLowerCase(), sel=D.ids();
      var min=D.num(val(r,"min")), nol=$("#f-nolimit",r).checked, max=nol?null:D.num(val(r,"max"));
      if(!name) return invalid("name","Enter the approver's name.");
      if(!emailOk(email)) return invalid("email","Enter a valid email address.");
      if(!sel.length){ var f=$('[data-field="scope"]',r); f.classList.add("invalid"); $(".err",f).textContent="Pick at least one sub-department."; f.scrollIntoView({block:"nearest"}); return false; }
      if(isNaN(min)||min<0) return invalid("min","Enter a starting amount of 0 or more.");
      if(!nol&&(isNaN(max)||max<=min)) return invalid("max","Must be more than the starting amount, or tick No upper limit.");
      var data={name:name,email:email,subs:sel,min:min,max:max};
      if(a) Object.assign(a,data); else S.authorities.push(Object.assign({id:uid("a"),active:true},data));
      return true;
    }});
}
function stageForm(s){
  openDialog({title:"Edit recipients",sub:s.name+": "+s.when,saveLabel:"Save recipients",done:"Recipients updated",
    chips:{to:s.to.slice(),cc:s.cc.slice(),support:s.support.slice()},
    body:chipField("to","To","Roles are filled in for each PR. For example, Approver means whoever is approving that PR.")+
      chipField("cc","Cc")+
      chipField("support","Support Cc","Support team members copied on this email. Add as many as you need."),
    setup:function(r){ paintChips(r,"to"); paintChips(r,"cc"); paintChips(r,"support"); },
    save:function(r){
      ["to","cc","support"].forEach(function(k){ var i=$("#ci-"+k,r); if(i.value.trim()) addChip(r,k,i.value,true); });
      if(!D.chips.to.length){ var f=$('[data-field="to"]',r); f.classList.add("invalid"); $(".err",f).textContent="Add at least one recipient."; return false; }
      s.to=D.chips.to; s.cc=D.chips.cc; s.support=D.chips.support;
      return true;
    }});
}

