var TABS=$$(".tab");
TABS.forEach(function(t,i){
  t.onclick=function(){ ui.view=t.getAttribute("data-view"); render(); };
  t.onkeydown=function(e){ var d=e.key==="ArrowRight"?1:e.key==="ArrowLeft"?-1:0; if(!d) return; var n=TABS[(i+d+TABS.length)%TABS.length]; n.click(); n.focus(); };
});

document.addEventListener("click",function(e){
  var b=e.target.closest("[data-action]"); if(!b||b.closest("#dialog")) return;
  var act=b.getAttribute("data-action"), id=b.getAttribute("data-id"), snap;
  var co=byId(S.companies,ui.company);
  function flip(o,k){ o[k]=!o[k]; render(); }
  switch(act){
    case "add-company": return companyForm();
    case "edit-company": return companyForm(byId(S.companies,id));
    case "pick-company": ui.company=id; ui.q.units=""; return render();
    case "del-company":
      var c=byId(S.companies,id);
      return confirmDel("Delete "+c.name+"?",(c.units.length?"This also deletes its "+plural(c.units.length,"unit")+". ":"")+"Existing PRs keep their company name.",function(){
        snap=snapshot(); S.companies.splice(S.companies.indexOf(c),1); ui.company=S.companies[0]&&S.companies[0].id; render(); toast(c.name+" deleted",snap); });
    case "add-unit": return unitForm();
    case "edit-unit": return unitForm(byId(co.units,id));
    case "toggle-unit": return flip(byId(co.units,id),"active");
    case "del-unit": var u=byId(co.units,id); snap=snapshot(); co.units.splice(co.units.indexOf(u),1); render(); return toast(u.name+" deleted",snap);

    case "add-dept": return deptForm();
    case "edit-dept": return deptForm(dept(id));
    case "toggle-dept": return flip(dept(id),"active");
    case "del-dept":
      var d=dept(id);
      return confirmDel("Delete "+d.name+"?","Its "+plural(d.subs.length,"sub-department")+" go with it, and approvers lose them from their scope. Users in this department will need a new one.",function(){
        snap=snapshot(); var sids=d.subs.map(function(s){ return s.id; });
        S.authorities.forEach(function(a){ a.subs=a.subs.filter(function(s){ return sids.indexOf(s)<0; }); });
        S.departments.splice(S.departments.indexOf(d),1); render(); toast(d.name+" deleted",snap); });
    case "toggle-sub": return flip(subOwner(id).s,"active");
    case "del-sub":
      var o=subOwner(id); snap=snapshot(); o.d.subs.splice(o.d.subs.indexOf(o.s),1);
      S.authorities.forEach(function(a){ a.subs=a.subs.filter(function(s){ return s!==id; }); });
      render(); return toast(o.s.name+" removed",snap);

    case "add-cat": return catForm();
    case "edit-cat": return catForm(byId(S.categories,id));
    case "toggle-cat": return flip(byId(S.categories,id),"active");
    case "del-cat": var k=byId(S.categories,id); snap=snapshot(); S.categories.splice(S.categories.indexOf(k),1); render(); return toast(k.name+" deleted",snap);

    case "add-auth": return authForm();
    case "edit-auth": return authForm(byId(S.authorities,id));
    case "toggle-auth": return flip(byId(S.authorities,id),"active");
    case "del-auth": var a=byId(S.authorities,id); snap=snapshot(); S.authorities.splice(S.authorities.indexOf(a),1); render(); return toast(a.name+" removed as approver",snap);

    case "edit-stage": return stageForm(byId(S.stages,id));
    case "toggle-stage": return flip(byId(S.stages,id),"enabled");
  }
});
document.addEventListener("input",function(e){
  var k=e.target.getAttribute&&e.target.getAttribute("data-search"); if(k){ ui.q[k]=e.target.value; render(); }
});
document.addEventListener("keydown",function(e){
  var t=e.target; if(!t.hasAttribute||!t.hasAttribute("data-addsub")||e.key!=="Enter") return;
  e.preventDefault(); var name=t.value.trim(), d=dept(t.getAttribute("data-addsub")); if(!name) return;
  if(d.subs.some(function(s){ return s.name.toLowerCase()===name.toLowerCase(); })){ toast(name+" already exists in "+d.name); return; }
  d.subs.push({id:uid("s"),name:name,active:true}); render(); toast(name+" added to "+d.name);
  var again=$('[data-addsub="'+d.id+'"]'); if(again) again.focus();
});

